    ('"It\'s high time we ___ a decision."', "made", ["make", "will make", "have made"], 'After "it\'s high time", use the past form.'),
    ('"The committee demanded that he ___ immediately."', "resign", ["resigns", "resigned", "will resign"], 'After "demand that", use the base verb (the subjunctive).'),
    ('"She would rather you ___ her before visiting."', "called", ["call", "will call", "to call"], '"Would rather" + another person takes the past form.'),
