GROUPS = [
    ("EASY", "VOCABULARY", EASY_VOCAB),
    ("EASY", "GRAMMAR", EASY_GRAMMAR),
    ("MEDIUM", "VOCABULARY", MEDIUM_VOCAB),
    ("MEDIUM", "GRAMMAR", MEDIUM_GRAMMAR),
    ("HARD", "VOCABULARY", HARD_VOCAB),
    ("HARD", "GRAMMAR", HARD_GRAMMAR),
]


def main():
    rng = random.Random(42)  # fixed seed, so the file is the same every run
    out = []
    for difficulty, qtype, items in GROUPS:
        assert len(items) == EXPECTED_PER_GROUP, (difficulty, qtype, len(items))
        for number, (question, correct, wrong, explanation) in enumerate(items, start=1):
            assert len(wrong) == 3 and correct not in wrong, question
            assert len(set(wrong)) == 3, question
            choices = wrong[:]
            position = rng.randrange(4)
            choices.insert(position, correct)
            out.append({
                "id": f"{difficulty[0]}{qtype[0]}{number:02d}".lower(),
                "type": qtype,
                "difficulty": difficulty,
                "question": question,
                "choices": choices,
                "answerIndex": position,
                "explanation": explanation,
                "explanationKo": KO[f"{difficulty[0]}{qtype[0]}{number:02d}".lower()],
            })
    assert len({q["question"] for q in out}) == len(out), "duplicate question text"
    assert set(KO) == {q["id"] for q in out}, "every question needs exactly one Korean explanation"
    path = os.path.join(os.path.dirname(__file__), "..", "app", "src", "main", "assets", "questions.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
        f.write("\n")
    print(f"Wrote {len(out)} questions")


if __name__ == "__main__":
    main()
